# Glossary rows for SETTLED: (term, definition, chapters, aliases)
# Sections: (anchor, title, intro, rows). The first chapter in `chapters` is the owning chapter (PLAN.md "Owns").
# Definitions follow the owning chapter's wording as read on 2026-11-17 (see harvest.py and kw.py to re-check).
# Provider-specific terms (PaymentIntent, balance account, ...) live in crosswalk.py, not here.
# Never write a | or a straight double quote inside a cell: use typographic quotes.

S = []

S.append(('g-reading', 'Preface — Reading the Claims, and the Sixteen Failure Patterns',
"These entries say how to read the book's statements and name the sixteen recurring failures. [[introduction]] sets out the six kinds of statement and the three tiers of take-away, [[how-payments-got-complicated]] introduces the basic vocabulary one step at a time, and [[where-payment-systems-go-wrong]] gives each failure pattern its warning sign and remedy.",
[
('The instant answer and the slow truth', "The book's central contrast: the answer a payment API returns in about two seconds is a promise, and the outcome is settled days or months later through capture, clearing, settlement, payout and the dispute window. The rule that follows is not to record a promise as the truth.", ['introduction'], ['Promise (a payment as a promise)', 'Slow truth']),
('When is it really paid, and who is on the hook until then?', 'The one question the preface asks of every way of paying, from cash to a platform payment; each later layer (credit, the check, the card network, the provider, the platform) moved the answer further from the moment of sale.', ['how-payments-got-complicated'], []),
('Documented fact', "A company's public statement, a network rule, a standard, a law or a number, attributed in the sentence with its year and listed under Sources and Evidence.", ['introduction'], []),
('Industry practice', 'What payment companies and integrators commonly do, phrased as “commonly” or “a typical design is”, with no invented percentages.', ['introduction'], []),
('Inference', 'How a system is plausibly built. When it concerns a real company it stands in a block marked INFERENCE, NOT DOCUMENTED and is never a description of that company\'s systems.', ['introduction'], ['INFERENCE, NOT DOCUMENTED', 'Reference-architecture inference']),
('Recommendation', "The author's judgement, in the first person, with reasons and the conditions under which it fails.", ['introduction'], []),
('Illustration', 'An example at Larkfield, the fictional studio-software platform the book follows; labeled fictional in each chapter and never evidence about a provider.', ['introduction', 'meet-larkfield'], []),
('Assumption', 'An illustrative fee, volume or latency that is neither documented nor a Larkfield fact, marked “assume…” or *(assumption)*; not a benchmark.', ['introduction'], ['Labeled assumption']),
('Not public', "The book's wording where no public source speaks. It is a dated search result (documentation, help center and site, November 2026), not proof that the thing does not exist.", ['introduction'], []),
('Evidence age', 'The mark on a source older than about three years, for example “(Evidence age: 9 years; the current system may differ)”; documentation pages are undated and cited “n.d., accessed November 2026”.', ['introduction'], []),
("Established / Depends on context / The author's synthesis", "The three tiers of every chapter's “What to Take Away”: what the field agrees on, with its evidence; a recommendation that holds under a stated condition; and the author's own position, to weigh and to disagree with.", ['introduction'], ['What to Take Away', 'Three tiers of take-away']),
('Stripe and Adyen: Where They Differ', "The required section of every chapter in Parts I–VIII: a table that sets, aspect by aspect, what each company has documented (with the year) beside what is not public; its last column is the author's reading and is inference.", ['introduction', 'stripe-and-adyen-bets-compared'], ['Where They Differ table']),
("Where we are in the payment's journey", "The short paragraph near the top of each chapter that places it on the path of Mila's class pass, the book's recurring payment.", ['introduction', 'meet-larkfield'], []),
('Failure pattern', 'A named, recurring way a payment system goes wrong, with a warning sign that can be checked in a review and one of four families. The book uses sixteen; each has the shape of a promise, or a silence, recorded as the truth.', ['where-payment-systems-go-wrong'], []),
('Money truth / Integration / Trust / Platform and scale', 'The four families of failure pattern: a record of money that nothing outside the system has confirmed; an untested assumption about the provider\'s interface; a control handed to the provider and then not watched; a dependency, a peak or a regulated role that nobody rehearsed or named.', ['where-payment-systems-go-wrong'], ['Money truth (family)', 'Integration (family)', 'Trust (family)', 'Platform and scale (family)']),
('The Double Charge', 'A timeout is retried as a new request, and the customer pays twice. Money truth family.', ['where-payment-systems-go-wrong', 'idempotency-and-retries'], []),
('The Phantom Payment', "A system believes a payment succeeded, or failed, without the provider's confirmed record saying so. Money truth family.", ['where-payment-systems-go-wrong', 'payment-state-machines'], []),
('The Orphaned Refund', 'Refunds, reversals and chargebacks arrive weeks later and nobody can tie them to the original payment. Money truth family.', ['where-payment-systems-go-wrong', 'refunds-reversals-and-disputes'], []),
('The Black-Box Balance', 'Money sits in a provider balance that nobody can break down into payments, fees, refunds and reserves. Money truth family.', ['where-payment-systems-go-wrong', 'balances-and-funds-flows'], []),
('The Stranded Payout', 'A payout is marked sent, never arrives or comes back, and no one owns the difference. Money truth family.', ['where-payment-systems-go-wrong', 'payouts-and-money-movement'], []),
('The Trusted Doorbell', 'Webhooks are treated as complete, ordered and delivered once. Integration family.', ['where-payment-systems-go-wrong', 'payment-webhooks-and-events'], []),
('The Version Cliff', 'An integration is pinned to an old API version until an upgrade is forced, all at once. Integration family. (Also the name of a Larkfield incident.)', ['where-payment-systems-go-wrong', 'payment-api-versioning'], []),
('A Card by Any Other Name', 'Every payment method is assumed to behave like a card: instant, capturable, refundable and disputable the same way. Integration family.', ['where-payment-systems-go-wrong', 'local-payment-methods'], []),
('The Vault Hostage', "Stored cards exist only as one provider's tokens, so the business cannot move. Trust family.", ['where-payment-systems-go-wrong', 'tokenization-vaulting-and-pci'], []),
('The Card in the Log', 'Card data reaches a system that was never meant to see it, and compliance scope grows silently. Trust family.', ['where-payment-systems-go-wrong', 'tokenization-vaulting-and-pci'], []),
('The Open Till', 'An endpoint that can start a payment has no limit, so attackers use it to test stolen cards. Trust family.', ['where-payment-systems-go-wrong', 'payment-fraud-and-risk'], []),
('The Frozen Seller', 'Verification is treated as a one-time form; a requirement changes and payouts stop. Trust family.', ['where-payment-systems-go-wrong', 'payment-compliance-and-regulation'], []),
('The Single Rail', 'Every payment depends on one provider, one acquirer or one region, and nobody has rehearsed the switch. Platform and scale family.', ['where-payment-systems-go-wrong', 'payment-routing-and-orchestration'], []),
('The First of the Month', 'A peak everyone could predict (renewals, a sale, a launch) meets limits nobody tested. Platform and scale family.', ['where-payment-systems-go-wrong', 'payment-peak-load'], []),
('The Borrowed Blueprint', 'An architecture is copied from a provider a thousand times larger without its reasons. Platform and scale family.', ['where-payment-systems-go-wrong', 'case-stripe'], []),
('The Accidental Bank', "A platform holds, moves or lends other people's money without knowing which license and liability that takes. Platform and scale family.", ['where-payment-systems-go-wrong', 'licences-and-safeguarding'], []),
]))

S.append(('g-money', 'Part I — MONEY: How a Payment Actually Moves',
"Part I's terms name the parties to a card payment and the steps between “pay” and “paid”: the approval, the claim, the record, the money, the routes back and the fees. Read *authorization*, *capture*, *clearing*, *settlement* and *payout* as five different events with five different owners ([[journey-of-a-payment]]).",
[
('Four-party model', "The standard picture of a card payment: the cardholder; the issuer, the cardholder's bank; the merchant, who sells; and the acquirer, the institution on the merchant's side. The card network stands between the two institutions, which makes five parties.", ['journey-of-a-payment'], ['Cardholder']),
('Issuer', "The bank that gave the cardholder the card and keeps the account behind it. It decides every authorization, and it is the party a cardholder complains to in a dispute.", ['journey-of-a-payment', 'payment-authorization'], ['Issuing bank']),
('Acquirer', "The licensed institution that accepts card payments on the merchant's behalf: it submits them to the card network as a member and is the first party to receive the money for them.", ['acquiring-and-network-connectivity', 'journey-of-a-payment'], ['Acquiring bank']),
('Card network', 'Visa, Mastercard or another network that carries the authorization request between acquirer and issuer, sets the rules and runs the daily settlement between its member banks. Adyen\'s documentation says “scheme”.', ['journey-of-a-payment'], ['Network', 'Card scheme']),
('Merchant', 'The party that sells and that the cardholder buys from. On a platform the card networks\' rules decide who that is; see sponsored merchant and merchant of record.', ['journey-of-a-payment', 'platform-payment-models'], []),
('Payment service provider (PSP)', "A company that packages some or all of gateway, processor, payment facilitator and acquirer behind one contract and one API; whether it is itself the acquirer depends on provider and country. The book says “the provider”, and “payment provider” in the preface.", ['journey-of-a-payment', 'how-payments-got-complicated'], ['PSP', 'Payment provider', 'The provider']),
('Payment facilitator (PayFac)', "An entity that signs many small merchants under one acquirer and pays them out; in Visa's rules it contracts with an acquirer “on behalf of a Sponsored Merchant”. Its acquirer registers it with the network and stays liable for it.", ['journey-of-a-payment', 'platform-payment-models'], ['PayFac', 'Payment facilitator']),
('Platform', 'Software through which other businesses sell and get paid. It holds funds only if it is licensed to; otherwise the money sits with a licensed provider.', ['journey-of-a-payment', 'platform-payment-models'], []),
('Three-party network', "A card network in which one company is both issuer and acquirer; Stripe's documentation gives American Express as the example of such a standalone network.", ['journey-of-a-payment'], ['Three-party scheme']),
('Bank-transfer scheme', "A way of paying in which the payer's bank and the merchant's bank deal with each other under the scheme's rules: the money is pushed by the payer or pulled by the merchant under a mandate.", ['journey-of-a-payment', 'local-payment-methods'], []),
('Wallet', "Two different things under one name: a saved payment credential, such as a tokenized card held on a phone, which changes how the card is presented and not the parties; or a stored balance held with the wallet provider.", ['journey-of-a-payment', 'network-tokens'], ['Phone wallet']),
('A message, then a record, then money', 'The fixed order in which three different things move in a card payment: the authorization is a message, clearing is a record, and settlement and payout are money. A status reports one of them, decided by one party.', ['journey-of-a-payment'], ['The payment timeline', 'Payment timeline']),
('Authorization', "The promise of the cardholder's bank to honor a claim for up to an approved amount inside a limited window. It moves no money; before the claim arrives it can lapse, shrink or be withdrawn.", ['payment-authorization'], ['Authorisation', 'Approval']),
('Hold', "What an approving issuer places on the cardholder's account: it lowers the amount the cardholder can spend by the approved amount without debiting the account.", ['payment-authorization', 'journey-of-a-payment'], []),
('Response code', "The issuer's answer to an authorization request: a two-character code in the response message. In practice it is usually uninformative (“05: Do not honor”), so providers add their own normalized reason and the network's retry advice.", ['payment-authorization'], ['Decline code']),
('Authorization validity window', "The time within which an approved payment must be captured. For a customer-initiated online Visa payment, Visa's rule and Adyen's page give 10 days and Stripe's page gives 7; a merchant-initiated Visa payment has 5.", ['payment-authorization'], ['Authorization expiry', 'Validity window']),
('Final authorization / pre-authorization / incremental authorization / partial authorization', 'A final authorization is for the exact amount and is the default on both providers; a pre-authorization is for an estimate; an incremental authorization raises an approved estimate; a partial authorization is the issuer approving less than was asked.', ['payment-authorization'], ['Final authorization', 'Pre-authorization', 'Incremental authorization', 'Partial authorization']),
('Zero-value authorization', 'An authorization that reserves nothing, sent to confirm that a card can be used before it is stored; Visa calls it an Account Verification.', ['payment-authorization'], ['Account verification', 'Zero-auth']),
('Reversal (authorization reversal)', "Giving the promise back: a message that cancels an approval before capture, so no payment appears on the cardholder's statement. Often called a cancel or a void; the word “reversal” shifts by provider (see the crosswalk).", ['payment-authorization', 'refunds-reversals-and-disputes'], ['Reversal', 'Cancel', 'Void', 'Authorization reversal']),
('Customer-initiated transaction (CIT) / merchant-initiated transaction (MIT)', 'A CIT is a payment the cardholder takes part in. An MIT is one the merchant starts from stored details while the cardholder is away, on the strength of a prior agreement; the label changes which rules, validity window and authentication duty apply.', ['payment-authorization', 'three-d-secure-and-sca'], ['CIT', 'MIT', 'Customer-initiated transaction', 'Merchant-initiated transaction']),
('Stored credential', "Card information kept by a merchant, its agent, a payment facilitator or a wallet operator to process future transactions. Visa's rules require the cardholder's agreement and an approved authorization or account verification before it is stored.", ['payment-authorization'], ['Card on file', 'Stored card']),
('Stand-in processing (STIP)', "The network answering an authorization on the issuer's behalf when the issuer is unavailable, too slow or has asked for it. Whether a given approval came from stand-in is not public for either provider.", ['payment-authorization'], ['STIP']),
('ISO 8583', "The card industry's message standard, in which an authorization request travels from the acquirer through the network to the issuer.", ['payment-authorization'], []),
('Capture', "The merchant's claim on an authorization: the instruction to collect the approved amount, sent automatically by default on both providers or later by the merchant (manual, delayed, partial or multiple capture).", ['clearing-and-settlement'], ['Manual capture', 'Partial capture']),
('Clearing', 'The exchange of records between acquirer and issuer through the network that fixes the final amount and data of a captured payment. It is a record, not money.', ['clearing-and-settlement', 'journey-of-a-payment'], []),
('Presentment', "In Visa's rules, “A Clearing Record that an Acquirer presents to an Issuer through Interchange”: the final statement of what was sold and for how much. In the rulebook “Interchange” means this exchange of records, not the fee.", ['clearing-and-settlement'], []),
('Dual-message / single-message network', 'A dual-message network uses separate messages to authorize and to clear a transaction, as online card payments typically do; a single-message network does both in one message and normally carries PIN-authenticated debit.', ['clearing-and-settlement'], ['Dual-message', 'Single-message']),
('Net settlement', "The network's daily transfer of money between its member banks, as one net amount per member, on the next business day or later. The networks' cut-off times and number of settlement cycles a day are not public.", ['clearing-and-settlement'], ['Settlement', 'Settlement cycle']),
('“Settled” (three meanings)', "At the network: the daily net amount has reached the acquirer. At the provider: funds are released to the merchant's balance or batch. At the merchant's bank: the payout has arrived. A payout date does not say when the banks settled.", ['clearing-and-settlement', 'journey-of-a-payment'], ['Settled']),
('Funding (pass-through, fixed-delay, instant)', "The provider's own step of making a sale's money payable to the merchant, on the provider's schedule: pass-through funding pays as each method's funds arrive; fixed-delay funding pays a whole day's sales after a set number of days; instant funding removes the delay for a fee.", ['clearing-and-settlement', 'balances-and-funds-flows'], ['Funding', 'Pass-through funding', 'Fixed-delay funding', 'Instant funding']),
('Refund', 'Money sent back to the customer at the merchant\'s request after capture. It is a new transaction that can itself fail, not an undo of the first.', ['refunds-reversals-and-disputes'], []),
('Dispute / chargeback', "A dispute is a cardholder's complaint to the issuer that a charge should be reversed; the chargeback is the forced return of the money through the network. The merchant does not start it, and it runs on the issuer's clock whatever has been settled and paid out.", ['refunds-reversals-and-disputes'], ['Dispute', 'Chargeback']),
('Reason code', 'The ground an issuer gives for a dispute. The grounds fall into four families, which Visa numbers as categories 10 to 13; the family decides what evidence could answer the claim.', ['refunds-reversals-and-disputes'], []),
('Representment / pre-arbitration / arbitration', "Representment is the merchant's side presenting the transaction again with evidence (Visa now calls it a Dispute Response); pre-arbitration is the last exchange between the two banks; arbitration is the network's ruling.", ['refunds-reversals-and-disputes', 'journey-dispute'], ['Representment', 'Pre-arbitration', 'Arbitration', 'Dispute response']),
('Dispute window', "The time in which a card payment can still be disputed: about 120 days after the sale under Visa's public rules, sometimes longer. Until it closes, nothing is final.", ['refunds-reversals-and-disputes', 'journey-of-a-payment'], []),
('Dispute monitoring program', "A network scheme that counts a merchant's fraud reports and disputes against its sales each month and fines or restricts those above a threshold; Visa's is the Visa Acquirer Monitoring Program (VAMP).", ['refunds-reversals-and-disputes'], ['VAMP', 'Visa Acquirer Monitoring Program']),
('Rapid Dispute Resolution', "Visa's pre-dispute service that lets merchants and payment facilitators automate accepting liability for a disputed transaction; the case is resolved through a refund and does not become a chargeback.", ['refunds-reversals-and-disputes'], ['Pre-dispute']),
('Friendly fraud', 'A legitimate cardholder makes a purchase and disputes it later, by accident or on purpose (also “first-party misuse”). It arrives under the same fraud code as a dispute over a stolen card.', ['refunds-reversals-and-disputes', 'payment-fraud-and-risk'], ['First-party misuse']),
('Merchant discount rate (MDR)', 'The total a merchant pays to accept a card payment: the sum of interchange, scheme fees and the acquirer\'s or provider\'s markup.', ['payment-economics'], ['MDR']),
('Interchange', "The fee the cardholder's bank (the issuer) receives on each card payment, set by the network as a default and capped by law for some cards. Not to be confused with the rulebook's “Interchange”, the exchange of clearing records.", ['payment-economics'], ['Interchange reimbursement fee (IRF)']),
('Scheme fee', 'What the card network charges on a payment, by value, number of messages or crossing a border. The kinds are public; the fee schedules are not.', ['payment-economics'], ['Network fee']),
('Markup', 'The part of the fee the acquirer or provider keeps for itself, set by contract.', ['payment-economics'], []),
('Blended pricing', 'One percentage plus a fixed amount for every payment of a kind, whatever the card behind it costs the provider.', ['payment-economics'], []),
('Interchange-plus-plus pricing (IC++)', "Pass-through pricing: the merchant pays the actual interchange and scheme fee of each payment plus the provider's fixed markup, so the provider's share is fixed and the total varies. Never compare a blended rate with a markup.", ['payment-economics'], ['IC++', 'Interchange++', 'Pass-through pricing', 'IC+']),
('Net revenue / take rate', 'Net revenue is what a provider keeps after passing interchange and scheme fees on; take rate is net revenue divided by the value of payments processed, usually in basis points (one basis point is 0.01%). Company-reported volume is not revenue.', ['payment-economics', 'case-adyen'], ['Net revenue', 'Take rate', 'Basis point']),
('Interchange Fee Regulation', 'Regulation (EU) 2015/751, which caps interchange on consumer cards of four-party networks at 0.2% of the value for debit and 0.3% for credit.', ['payment-economics'], ['IFR']),
('Durbin amendment / Regulation II', 'The US statute and the Federal Reserve regulation that cap debit interchange for covered issuers ($0.21 plus 0.05% of the value, plus a $0.01 fraud-prevention adjustment) and forbid restricting a debit card to fewer than two unaffiliated networks, which is what allows least-cost routing.', ['payment-economics', 'payment-routing-and-orchestration'], ['Durbin amendment', 'Regulation II']),
]))

S.append(('g-acceptance', 'Part II — ACCEPTANCE: Getting to Yes',
"Part II's terms cover the provider's side of the authorization message: who may send it and under which license, what “yes” means for a method that is not a card, how a payment is modeled as states, and what changes when several providers or a terminal are involved. Provider-specific names such as PaymentIntent and modification are in the [crosswalk](#g-x-payments).",
[
('Acquirer of record', "This book's name for the entity that holds the acquirer's role for a given payment. The question to put to a provider first: which legal entity is the acquirer for these sellers, in this country?", ['acquiring-and-network-connectivity'], []),
('Principal member / associate member', "Tiers of card-network membership. In Visa's rules a principal-type member licenses its own network identifiers and is liable for all activity on them; an associate-type member uses an identifier licensed to its sponsor, which is liable where the associate cannot meet its responsibility.", ['acquiring-and-network-connectivity'], ['Principal membership', 'Associate member']),
('BIN / acquiring identifier', 'The network identifiers a member licenses: a bank identification number (BIN) for issuing and an acquiring identifier for acquiring. Liability follows the identifier.', ['acquiring-and-network-connectivity'], ['BIN', 'Bank identification number']),
('Sponsor bank', 'The acquiring bank under whose network membership a payment facilitator or another non-member signs up merchants; the bank stays liable to the network for them.', ['acquiring-and-network-connectivity', 'licences-and-safeguarding'], ['Sponsoring bank']),
('Processor / gateway', 'A processor (acquirer processor) runs the technical connection and message processing for an acquirer; a gateway carries payment data from the merchant to an acquirer or processor. Neither holds the membership or the money.', ['acquiring-and-network-connectivity', 'journey-of-a-payment'], ['Processor', 'Gateway', 'Acquirer processor']),
('Local acquiring', "Having an acquirer whose license reaches the country of the sale, so that the business sells there as a local merchant and that country's cards do not arrive at their issuers as international payments.", ['acquiring-and-network-connectivity'], []),
('MID (merchant ID)', 'The account number an acquirer gives a merchant.', ['payment-routing-and-orchestration'], ['Merchant ID']),
('Payment method', 'A way of paying that runs on a scheme: a body of rules plus the banks and companies that follow them. (In this sense “scheme” is wider than Adyen\'s use of the word for a card network.)', ['local-payment-methods'], ['Scheme (payment scheme)']),
('Payment method family', 'A group of payment methods that behave alike after `paid`: cards, bank debits, bank redirects, bank transfers, wallets, buy now pay later, real-time payments, vouchers. The family, not the brand, is the unit to design for: keep one policy per family.', ['local-payment-methods'], ['Method family']),
('Push / pull', "In a push the payer instructs their own bank to send money; in a pull the merchant instructs the payer's bank to take money under a permission given earlier.", ['local-payment-methods'], ['Push payment', 'Pull payment']),
('Account-to-account payment', 'A payment that moves money between two bank accounts with no card network in between.', ['local-payment-methods', 'payments-what-is-moving'], ['A2A']),
('Finality', 'The point after which the payer can no longer take a payment back through their bank. It differs by method: an iDEAL payment cannot be disputed with the payer\'s bank, while a SEPA direct debit can be disputed without a reason for eight weeks.', ['local-payment-methods'], []),
('Mandate', "The payer's standing permission for a named creditor to debit their account: a record somebody must be able to produce years later.", ['local-payment-methods'], []),
('Direct debit', "A pull from the payer's bank account under a mandate, which can be returned weeks later. SEPA Direct Debit is the scheme of the Single Euro Payments Area; Bacs Direct Debit the British one; ACH the US one.", ['local-payment-methods', 'invoicing-collections-and-dunning'], ['SEPA Direct Debit', 'Bacs Direct Debit', 'ACH', 'SEPA']),
('Redirect flow', "A checkout in which the customer leaves the merchant's page to approve the payment at their bank, and may not come back. iDEAL (the Netherlands; being replaced by Wero) and Bancontact (Belgium) work this way.", ['local-payment-methods'], ['iDEAL', 'Bancontact', 'Wero']),
('Charge-request model', "The older model in which a payment is one server call that carries the card details and returns the outcome, and the merchant's record is that answer. It broke on payments that need a customer action or finish later.", ['payment-state-machines'], []),
('Payment state machine', 'A record created on the server before any money moves, which holds a state, the transitions allowed from that state and every attempt made to pay. It must guarantee one terminal outcome, legal transitions and idempotent transitions.', ['payment-state-machines'], []),
('Next action', "The provider's instruction to the client about what the customer must do before the payment can go on: a redirect, a 3-D Secure challenge, a voucher to pay.", ['payment-state-machines'], []),
('Authorization rate / payment success rate / checkout conversion', "Three rates with three denominators. Stripe's authorization rate divides payments authorized by the issuer by unique attempts submitted to the network; payment success rate divides them by attempts submitted through the provider; checkout conversion is completed payments over checkouts started.", ['authorization-optimization'], ['Authorization rate', 'Approval rate', 'Payment success rate', 'Checkout conversion']),
('Blocked payment', 'A payment the provider stops itself before it reaches the card network, as a risk block or to save a fee; it leaves the authorization-rate denominator.', ['authorization-optimization', 'payment-fraud-and-risk'], ['Risk block']),
('Soft decline / hard decline', 'A soft decline is a refusal that might become an approval later or with corrected data; a hard decline will not change for this card. Both are industry shorthand, not network terms: the network vocabulary is Visa\'s decline-code categories and Mastercard\'s merchant advice code.', ['authorization-optimization', 'invoicing-collections-and-dunning'], ['Soft decline', 'Hard decline']),
('Account updater', "A card-network service that gives the provider a replaced card's new number or expiry date, so a stored card keeps working after the bank reissues it.", ['authorization-optimization', 'invoicing-collections-and-dunning'], ['Card updater']),
('Routing / routing rule', 'Routing is the choice of path for one payment; a routing rule is the stated condition that makes the choice, such as “payments for this studio go to this provider”.', ['payment-routing-and-orchestration'], ['Routing', 'Routing rule']),
('Least-cost routing', 'Sending each debit payment over whichever of the networks the card can travel on costs less in fees.', ['payment-routing-and-orchestration', 'payment-economics'], []),
('Payment orchestration', 'A layer in front of two or more providers that decides, per payment, which one processes it. Its parts are one payment API, a rule engine, an adapter per provider, a credential store and an attempt record.', ['payment-routing-and-orchestration'], ['Orchestration', 'Adapter', 'Credential store', 'Attempt record']),
('Failover', 'Sending payments to a second provider when the first is failing; the simplest use of orchestration, and worth little unless it has been rehearsed.', ['payment-routing-and-orchestration', 'payment-reliability-and-availability'], []),
('Forwarding proxy', 'A provider service to which you send a request addressed to a third party with placeholders for the card details; the provider fills them in from its vault and sends it on.', ['payment-routing-and-orchestration', 'tokenization-vaulting-and-pci'], []),
('Card-present payment', 'A payment where a terminal reads the physical card, or a phone standing in for it.', ['in-person-payments'], ['Card-present', 'Card-not-present']),
('EMV', "The chip-card standard, named after Europay, Mastercard and Visa: the chip generates a one-time cryptogram for each transaction, whether the card is inserted or held near the reader (contactless).", ['in-person-payments'], ['Chip', 'Contactless']),
('EMV liability shift', "The network rule under which an issuer may dispute a counterfeit-card fraud on a chip card when the payment was not read at a chip-reading device or the full chip data was not passed on, so the loss falls on the merchant's side. It works through disputes and is not a law.", ['in-person-payments'], []),
('Payment terminal', 'A certified computer with an expiry date that reads cards at a counter: a managed device with a fleet, software updates and keys.', ['in-person-payments'], ['Terminal']),
('Point-to-point encryption (P2PE)', "A solution validated against PCI's standard that protects card data from the point where the merchant accepts the card to the secure point of decryption. Both providers encrypt end to end (E2EE) by default and offer validated P2PE as an option.", ['in-person-payments'], ['P2PE', 'E2EE', 'End-to-end encryption']),
('Terminal API', 'The interface through which point-of-sale software drives a terminal, either inside the store (local) or through the provider\'s platform (cloud).', ['in-person-payments'], []),
('Offline payment (offline EMV / store-and-forward)', 'Two different things. In offline EMV the terminal checks the PIN against the chip and asks the card to approve. In store-and-forward the terminal approves without any verification, stores the payment and sends it for authorization when the connection returns: credit extended by the merchant.', ['in-person-payments'], ['Offline EMV', 'Store-and-forward', 'Offline payment']),
('Unified commerce', 'Treating a store payment and an online payment as one. In data terms it is three separate checks: a shared identifier for the payer, a refund that crosses channels, and one settlement report covering both.', ['in-person-payments', 'case-adyen'], ['Omnichannel']),
('Tap to pay on a phone', 'Accepting contactless cards on an ordinary phone: it removes the terminal hardware and keeps the acquirer and the certification.', ['in-person-payments'], ['Tap to Pay']),
]))

S.append(('g-ledger', 'Part III — LEDGER: Recording and Moving Money',
"Part III's terms describe how a payment company records whose money it holds, what it owes a merchant at each moment, how that money leaves, how the records are proved against one another, and who is allowed to hold it. The contrasts that matter are *pending* versus *available*, *sent* versus *arrived*, and a *webhook* versus a *report*.",
[
('Ledger (double-entry ledger)', 'An append-only record in which every movement of value is written as lines that balance, so that a missing movement shows up as an account that does not empty. The simplest form, a list of who owes whom, is as old as credit at the village shop.', ['payment-ledgers', 'how-payments-got-complicated'], ['Ledger', 'Double-entry ledger', 'Double entry']),
('Account / entry', 'An account is a named bucket of value with a balance, such as “owed to Studio Noord”. An entry is a set of signed lines, each against one account, that sum to zero.', ['payment-ledgers'], ['Account (ledger)', 'Entry']),
('Immutable entry', 'A ledger entry is never edited or deleted; a mistake is corrected by a further entry.', ['payment-ledgers'], []),
('Clearing account', 'An account that holds an amount only while a process with several steps is in flight, and must return to zero when the process completes.', ['payment-ledgers'], []),
('Fund flow', "The fixed path an amount takes through accounts for one kind of business event: a state machine in which the accounts are the states and the entries the transitions. The term is Stripe's (2024).", ['payment-ledgers'], ['Funds flow']),
('Balance (merchant balance)', "The net amount the provider's books say it owes the merchant at a given moment: sales credited, less everything debited, less what has already been paid out. The merchant holds a claim, not money.", ['balances-and-funds-flows'], ['Balance', 'Merchant balance']),
('Pending funds / available funds', 'Pending funds are owed to the merchant and not yet payable; available funds are payable now and are what refunds are taken from. Adyen uses the two words differently (see the crosswalk).', ['balances-and-funds-flows'], ['Pending funds', 'Available funds']),
('Reserve', 'Money owed to the merchant but held back by the provider against refunds and chargebacks that may still come. The word names a different thing at Adyen (see the crosswalk).', ['balances-and-funds-flows'], []),
('Negative balance', 'A balance in which the debits exceed the credits, so the merchant owes the provider.', ['balances-and-funds-flows', 'splits-balances-and-platform-payouts'], []),
('Pre-funding', 'The provider paying the merchant before the network has paid the provider, and carrying that risk. Documented for Adyen\'s sales-day payout (capped at 30 days, then reversed) and, at Stripe, for Instant Payouts only.', ['balances-and-funds-flows', 'clearing-and-settlement'], ['Pre-financing']),
('Payout', 'The provider sending money it owes you, from a balance in its own books, to a bank account outside the provider. It is two processes that finish at different times: the accounting debit and the delivery by a bank network.', ['payouts-and-money-movement'], []),
('Payout rail', 'The bank network that carries a payout to the receiving bank, such as SEPA Credit Transfer, SEPA Instant, ACH, Faster Payments or a wire.', ['payouts-and-money-movement'], ['Rail']),
('Cut-off time / value date', "A rail's cut-off time is the point after which an instruction waits for the next processing cycle. The value date is the date from which the receiving bank counts the money as the payee's.", ['payouts-and-money-movement'], ['Cut-off time', 'Value date']),
('Payout return', 'The receiving bank sending the money back after the rail accepted the transfer. It reaches the sender as a new transaction, days after the payout was marked sent.', ['payouts-and-money-movement'], ['Returned payout']),
('Return window', "The time a sent payout is kept open before it is marked arrived by inference. No source gives an upper bound, so the window is a policy you choose, and a later return must still be handled.", ['payouts-and-money-movement'], ['Sent versus arrived']),
('Instant payout', 'A payout over a rail that reports the credit within seconds or minutes, sold by both providers with a fee and a ceiling.', ['payouts-and-money-movement'], []),
('Verification of payee / Confirmation of Payee', "A check, before a transfer is sent, that the name given matches the name on the receiving account. Verification of payee is the EU's rule (applied in the euro area since 9 October 2025); Confirmation of Payee is the older UK service.", ['payouts-and-money-movement'], ['Verification of payee', 'Confirmation of Payee', 'VoP', 'CoP']),
('IBAN', 'International bank account number. Bank transfers are routed by account identifier and not by name, which is why a misdirected payout succeeds.', ['payouts-and-money-movement'], []),
('Reconciliation', 'Showing that two independently written records of the same money agree, and explaining every difference.', ['payment-reconciliation-and-reporting', 'how-payments-got-complicated'], []),
('Provider-side reconciliation', "The provider reconciling its own ledger against two outside records: the clearing file, in which a network or acquirer lists each transaction it processed and what it will pay, and the bank statement.", ['payment-reconciliation-and-reporting'], ['Clearing file', 'Bank statement']),
('Exception / exception aging', 'An exception is an item that does not match. Exception aging means recording how long each has been open and who owns it; age separates timing differences from missing money.', ['payment-reconciliation-and-reporting'], ['Exception', 'Exception aging']),
('Settlement report', "The provider's itemized file of what it has settled and paid, with fees and adjustments, as of a stated cut-off. A report is complete and late; a webhook is prompt and incomplete. They are different contracts.", ['payment-reconciliation-and-reporting'], ['Report']),
('Event-fed / report-driven / warehouse-driven close', "Three ways to close a day: post every webhook to the books as it arrives; trust the provider's report as of its cut-off; or make the same match with queries on exported data.", ['payment-reconciliation-and-reporting'], ['Event-fed close', 'Report-driven close', 'Warehouse-driven close']),
('Bank (credit institution)', "An undertaking that takes deposits and grants credits for its own account. Money left with a bank becomes the bank's own asset, which it may lend, and the customer holds a claim on the bank.", ['licences-and-safeguarding'], ['Credit institution', 'Banking license']),
('Payment institution', "A licensed non-bank that may move customers' money and may not treat it as its own.", ['licences-and-safeguarding'], []),
('Electronic money institution (e-money institution)', "A licensed non-bank that may, in addition, keep a customer's money as a stored balance (e-money) to spend or withdraw later; it must hold those funds apart from its own and may not lend them.", ['licences-and-safeguarding'], ['E-money institution', 'EMI']),
('Money transmitter', 'In the United States, a non-bank that holds or moves money for others, licensed state by state.', ['licences-and-safeguarding'], ['Money transmitter license (MTL)']),
('Partner bank', "A licensed bank that a non-bank relies on for what only a bank may do: card-network membership (then called a sponsor bank) or deposit accounts.", ['licences-and-safeguarding', 'case-stripe'], []),
('For-benefit-of (FBO) account', 'One bank account held for many customers, where the bank sees a single balance.', ['licences-and-safeguarding'], ['FBO account']),
('Safeguarding', "What the law makes a licensed non-bank do with money it may not use: keep it apart from its own funds, in a separate account at a bank or in secure, low-risk assets, protected from the firm's other creditors.", ['licences-and-safeguarding'], ['Segregation of client funds']),
]))

S.append(('g-interface', 'Part IV — INTERFACE: The API as the Product',
"Part IV's terms describe the contracts an API gives the developer for each case one call hides: an identity and a state, a key that makes a request safe to repeat, a pinned version, events for outcomes that arrive later, and the limits within which each holds.",
[
('Resource model / command API', 'A resource model is the set of things an API gives an identifier and lets you read again. The alternative is an API of commands: calls that do something and return a result, leaving nothing to fetch.', ['payment-api-design'], ['Resource model', 'Command API']),
('Stable identifier / normalized vocabulary', 'Two of the three things integrator code should depend on: an identifier for each payment that does not change with the method, and one vocabulary of states and refusal reasons into which each new answer is mapped. The third is an explicit line between what the response answers and what arrives later.', ['payment-api-design'], ['Stable identifier', 'Normalized vocabulary']),
('Expandable object', 'A related object that the API returns as an identifier by default and as the full object on request.', ['payment-api-design'], []),
('Metadata', 'Key-value pairs the provider stores and returns without interpreting; the usual place for your own identifier.', ['payment-api-design'], []),
('Error model (no answer / rejected / refused)', 'How an API says what went wrong. For payments it must keep three outcomes apart: no answer (a timeout; unknown whether anything happened), rejected (the provider turned the request away; nothing happened) and refused (the issuer said no).', ['payment-api-design'], ['Error model', 'Rejected', 'Refused']),
('API family', 'A group of endpoints with its own version counter and conventions, and usually its own host, built for one kind of job.', ['payment-api-design'], []),
('Idempotent', 'Said of an operation that can be called any number of times while its side effects occur only once.', ['idempotency-and-retries'], ['Idempotency']),
('Idempotency key', 'An identifier sent with a request so that the provider can recognize a repeat of the same request and not perform it twice. It makes the request repeatable; it does not make the outcome known.', ['idempotency-and-retries'], []),
('Request fingerprint', "The server's stored record of what the first request asked for (its parameters, or a hash of them), used to tell a true repeat from a different request sent under the same key.", ['idempotency-and-retries'], []),
('Recovery point', 'In a stored idempotency record, the name of the last step that completed, so that a retried request resumes there.', ['idempotency-and-retries'], []),
('Unknown outcome', 'The state in which the client cannot tell whether money moved, typically after a timeout. A request has three outcomes, not two: approved, declined and unknown.', ['idempotency-and-retries', 'payment-authorization'], []),
('Business event (as the source of a key)', 'The thing a customer or a schedule meant to happen once: a cart, an invoice, a renewal attempt, a refund request, a payout period. The key is derived from it and stored before the first send; a deliberate new attempt is a new business event.', ['idempotency-and-retries'], ['Business event']),
('Retry policy', 'The rule for which failures are retried, after what wait and how many times. For failed requests it means backoff with jitter under the same key; for refused payments it says which refusals are retried and when, within the networks\' limits.', ['idempotency-and-retries', 'authorization-optimization'], []),
('API version', 'The shape of the API one integration sees. The provider remembers it on your behalf for years, so that an integration written long ago keeps working while the API changes around it.', ['payment-api-versioning'], []),
('Breaking change', 'A change to an API after which client code that was correct can fail or misbehave without having been modified.', ['payment-api-versioning'], []),
('Version pinning', "Fixing the version of the API that one integration sees, so that the provider's changes reach it only when it asks for a newer version. A pin works like a loan: it buys time, and the amount owed grows with every release.", ['payment-api-versioning'], ['API version pinning', 'Pin']),
('Version-change module', "Stripe's published mechanism (2017) for serving old versions: each incompatible change is encapsulated in a module that documents it and transforms the response for callers on an older version.", ['payment-api-versioning'], []),
('Deprecation policy', "A provider's published lifecycle that ends old versions after a stated notice period.", ['payment-api-versioning'], []),
('Event', "The provider's record that the state of something changed.", ['payment-webhooks-and-events'], []),
('Webhook', 'The delivery of an event as an HTTP request to an endpoint you registered. It is a notice to store and then confirm against the provider\'s own record, not the record itself.', ['payment-webhooks-and-events'], []),
('At-least-once delivery', 'Every event is delivered one or more times; no sender can promise exactly once across a network. Its consequences are the duplicate (an event that comes a second time) and disorder (an older event arriving after a newer one).', ['payment-webhooks-and-events'], ['Duplicate', 'Disorder']),
('Retry window', 'The period after which an unacknowledged event is not sent again.', ['payment-webhooks-and-events'], []),
('Signature verification', 'Recomputing a keyed hash (an HMAC, hash-based message authentication code) over the received message with a secret only you and the provider hold, to prove who sent it and that nobody changed the signed part.', ['payment-webhooks-and-events'], ['HMAC']),
('Snapshot event / thin event', 'A snapshot event carries a copy of the object as it was when the event was created, in the shape of one API version; a thin event carries only the type and identifiers, so the receiver has to fetch the current object.', ['payment-webhooks-and-events'], ['Snapshot event', 'Thin event']),
('Sweep (pending-payment job)', "A job that takes every payment pending longer than a set time and resolves it from the provider's record; needed for the events that never arrive. (Adyen uses “sweep” for a scheduled payout from a balance account; see the crosswalk.)", ['payment-webhooks-and-events'], ['Sweep']),
('Least privilege', 'Each calling system holds a credential that can do its own task and nothing else.', ['payment-developer-platform'], []),
('Test environment', 'A copy of the API in which calls create simulated objects and no card network or bank is contacted; a test card is a card number that works only there and returns a known result.', ['payment-developer-platform'], ['Test mode', 'Sandbox', 'Test card']),
('Rate limit', 'A cap on what one caller may send; a caller who exceeds it gets HTTP 429. A refusal for this reason is not a failed payment.', ['payment-developer-platform', 'payment-peak-load'], []),
('Load shedding', "Dropping lower-priority requests from everyone when the system itself is overloaded, so that critical ones keep working; the decision rests on the state of the whole system, not on who is calling.", ['payment-developer-platform'], []),
('Token bucket', 'A counter refilled at a fixed rate: each request takes a token and waits when none is left. Used by providers to limit and by clients to pace a batch below a limit.', ['payment-developer-platform', 'payment-peak-load'], []),
]))

S.append(('g-trust', 'Part V — TRUST: Card Data, Fraud, Authentication and Compliance',
"Part V's terms cover five controls, each defined by a rule that assigns responsibility: who may see a card number, what stands in for it, how fraud is estimated, how the payer is authenticated and what a provider must know about its customers. Legal entries summarize the rule as of November 2026; the cited source wins.",
[
('PCI DSS', 'The Payment Card Industry Data Security Standard: the card industry\'s security standard for anyone who stores, processes or transmits card data.', ['tokenization-vaulting-and-pci'], ['Payment Card Industry Data Security Standard']),
('Primary account number (PAN)', "The card number, the main thing PCI DSS protects.", ['tokenization-vaulting-and-pci'], ['PAN', 'Card number']),
('PCI DSS scope / cardholder data environment', 'Scope is the set of systems the standard reaches. Its core, the cardholder data environment, is every server, queue, log and support tool that stores, processes or transmits a card number, plus anything that can affect their security. Scope is decided by architecture.', ['tokenization-vaulting-and-pci'], ['Scope', 'Cardholder data environment', 'CDE', 'PCI scope']),
('Self-assessment questionnaire (SAQ)', 'The form on which a business attests that it meets PCI DSS. Which one applies follows from the integration: SAQ A when every card input is on a page or in a frame the provider serves, SAQ A-EP when your own page hosts the form, SAQ D when your systems are on the path.', ['tokenization-vaulting-and-pci'], ['SAQ', 'SAQ A', 'SAQ A-EP', 'SAQ D']),
('Hosted field', "A card input inside an iframe that the provider serves from its own domain. Your page decides where it sits and how it looks, and the browser's same-origin policy stops your scripts from reading what is typed.", ['tokenization-vaulting-and-pci'], ['Hosted fields']),
('Script criterion', 'The line of SAQ A that asks you to confirm your page cannot be used for a script attack; it applies to a page that embeds the provider\'s payment form and not to one that redirects.', ['tokenization-vaulting-and-pci'], []),
('Token / provider token', "A token is a reference that stands for a card number. A provider token is an identifier for a stored card that only this provider can turn back into a card number, so it works only there.", ['tokenization-vaulting-and-pci', 'how-payments-got-complicated'], ['Token', 'Provider token', 'Tokenization']),
('Vault', "The provider's store of real card numbers, kept apart from its own other systems so that most of the provider cannot see a card number either.", ['tokenization-vaulting-and-pci'], []),
('Network token', 'A substitute card number that the card network issues for one card at one merchant or device and maps back to the real card during authorization. It stays valid when the card is reissued.', ['network-tokens'], ['EMV payment token']),
('Token requestor', 'The party that asks the network for a network token and is the only party that may use it; in practice the provider or the wallet.', ['network-tokens'], []),
('Token service provider', 'The party that issues a network token and holds the mapping to the card; in practice the card network\'s token service.', ['network-tokens'], ['TSP']),
('Provisioning', 'The request that creates a network token: the requestor sends the card number to the network, the issuer approves and the network issues the token. The issuer can say no.', ['network-tokens'], []),
('Cryptogram', "A one-time value generated for one use of one token (or, on a chip card, for one transaction), proving that the request comes from the token's legitimate holder.", ['network-tokens', 'in-person-payments'], []),
('Domain control', 'The restriction of a network token to the party, channel or device it was requested for: a token stolen from one merchant or provider is useless at another, which is also why a token belongs to its requestor.', ['network-tokens'], []),
('Device token', 'A network token whose requestor is a phone wallet and whose restriction is the device; the cryptogram is produced when the owner unlocks the phone.', ['network-tokens', 'journey-card-payment'], []),
('Credential lifecycle', "What happens to a stored card over time: when the bank reissues the card, the network re-points the network token to the new card, so the stored credential keeps working without the customer doing anything.", ['network-tokens'], []),
('Card testing', 'Trying stolen card numbers on a small payment at one merchant to learn which still work before using them elsewhere. The tested merchant pays the fees.', ['payment-fraud-and-risk'], []),
('Account takeover / merchant fraud', 'Account takeover: a criminal logs in as a real customer and pays with the stored card. Merchant fraud: a fraudulent business takes payments without providing the goods or services, and the loss falls on the platform or provider if the seller\'s funds are gone.', ['payment-fraud-and-risk'], ['Account takeover', 'Merchant fraud']),
('Risk score', "The provider's estimate of how likely a payment is to end in a fraud dispute. A provider does not detect fraud during an authorization; it estimates and blocks above a threshold.", ['payment-fraud-and-risk'], []),
('Fraud signal', 'An input to the risk estimate; most of its value comes from the provider seeing many merchants.', ['payment-fraud-and-risk'], []),
('False positive', 'A legitimate payment refused as fraud; because fraud is rare, the commonest error. The threshold is a price with two costs, fraud accepted and good customers refused.', ['payment-fraud-and-risk'], []),
('Label / holdout / feedback loop', "A label is the after-the-fact record that a payment was fraud, usually a dispute that arrives weeks later. A holdout is a small share of payments let through whatever their score so their outcomes can be seen. Without it the system's own decisions determine which outcomes it will later see: the feedback loop.", ['payment-fraud-and-risk'], ['Label', 'Holdout', 'Feedback loop']),
('Credit exposure', "What a provider or platform stands to lose on an account if its refunds and chargebacks exceed the funds it can still reach.", ['payment-fraud-and-risk', 'splits-balances-and-platform-payouts'], ['Exposure']),
('Strong customer authentication (SCA)', "The EU's requirement, from PSD2, that the payer be authenticated with two or more independent elements of knowledge, possession and inherence. A merchant-initiated payment is outside the rule, because the payer is not initiating.", ['three-d-secure-and-sca'], ['SCA']),
('PSD2', "The EU's second Payment Services Directive, (EU) 2015/2366: the current payment services law, source of strong customer authentication, the payment institution license and safeguarding.", ['three-d-secure-and-sca', 'licences-and-safeguarding'], ['Payment Services Directive']),
('PSD3 / Payment Services Regulation (PSR)', 'The EU directive and regulation that will replace PSD2. Not adopted on 17 November 2026: “Awaiting Parliament 2nd reading”.', ['payment-compliance-and-regulation', 'payments-what-is-moving'], ['PSD3', 'PSR']),
('Exemption', 'A case, listed in the technical standards, in which a provider may skip the two factors. The low-risk exemption (transaction risk analysis) is rationed by the provider\'s own fraud rate.', ['three-d-secure-and-sca'], ['Transaction risk analysis (TRA)', 'SCA exemption']),
('3-D Secure', "The card networks' protocol for letting the issuer authenticate the payer of an online payment. Three parties each run one component: a 3DS server on the merchant's side, a directory server (DS) at the network and an access control server (ACS) at the issuer.", ['three-d-secure-and-sca'], ['3DS', 'EMV 3-D Secure', 'Directory server', 'Access control server (ACS)']),
('Frictionless flow / challenge flow', 'In a frictionless flow the issuer authenticates in the background from the data it is sent, with no further action by the customer; in a challenge flow it asks the customer to act, for example in a banking app.', ['three-d-secure-and-sca'], ['Frictionless flow', 'Challenge flow', 'Challenge']),
('Liability shift', "The card networks' rule that a payment authenticated through 3-D Secure, if later disputed as fraud, is the issuer's loss and not the merchant's. It covers fraud disputes only.", ['three-d-secure-and-sca'], []),
('Data-only flow', 'Using the 3-D Secure channel to share data with the network while requesting no authentication.', ['three-d-secure-and-sca'], []),
('Passkey', "A credential held on the customer's device and unlocked by a fingerprint or face scan; the card networks' versions are in pilot.", ['three-d-secure-and-sca', 'payments-what-is-moving'], ['Scheme passkey']),
('KYC / KYB', 'Know your customer and, for a business customer, know your business: the duty of a firm that moves money (an obliged entity under anti-money-laundering law) to know who its customers are.', ['payment-compliance-and-regulation'], ['KYC', 'KYB', 'Obliged entity', 'AML']),
('Beneficial owner', "Any natural person who ultimately owns or controls a legal entity; the EU's AML Regulation sets the ownership test at 25% or more.", ['payment-compliance-and-regulation'], []),
('Sanctions screening / PEP screening', 'Sanctions screening compares the business and its owners with government lists of persons nobody may deal with. A politically exposed person (PEP) is not forbidden as a customer but gets closer checks.', ['payment-compliance-and-regulation'], ['Sanctions screening', 'Politically exposed person (PEP)', 'PEP']),
('Transaction monitoring', "Watching transactions throughout a business relationship to check that they are consistent with what the firm knows of the customer; a suspicion is reported, confidentially, to the country's financial intelligence unit.", ['payment-compliance-and-regulation'], []),
('Prohibited and restricted businesses', "A provider's own list, on top of the law, of businesses it will not serve or serves only with approval; a lawful business can still be refused.", ['payment-compliance-and-regulation'], []),
('Capability / requirement / deadline', 'The three things in which both providers hold the result of verification. A capability is a named permission on an account, such as taking card payments or receiving payouts; a requirement is a missing fact or document; a deadline is the date by which it must be met, after which the capability is switched off.', ['platform-onboarding-and-verification', 'payment-compliance-and-regulation'], ['Capability', 'Verification requirement', 'Requirement', 'Deadline']),
('The form / the pass-through / the mirror', "Three ways a platform can hold verification. The form stores nothing after sign-up; the pass-through stores a yes or no per seller and leaves the rest to the provider's hosted pages and notices; the mirror stores each seller's requirements, deadlines and capability status, with an owner.", ['payment-compliance-and-regulation', 'platform-onboarding-and-verification'], ['The mirror (verification)']),
('Re-verification', "A provider asking again, months or years after onboarding, for confirmation that what it knows about a business is still true. Verification is a standing state on an account, not a decision per payment.", ['payment-compliance-and-regulation'], ['Periodic review']),
('DORA', 'The Digital Operational Resilience Act, Regulation (EU) 2022/2554, in application since 17 January 2025: incident reporting and a register of technology suppliers become legal duties. It imposes no data-localization obligation.', ['payment-compliance-and-regulation', 'payment-multi-region-and-data-residency'], []),
("EU AML Regulation", 'Regulation (EU) 2024/1624, the directly applicable anti-money-laundering rulebook that applies from 10 July 2027; until then national laws under the earlier directive apply.', ['payment-compliance-and-regulation'], ['AMLR']),
]))

S.append(('g-revenue', 'Part VI — REVENUE: Billing, Tax and Recognition',
"Part VI's terms belong to the second state machine above the payment: what is owed, for which period, when to ask, and what happens when the first attempt fails. Read *invoice* beside *payment*, and *billings* beside *cash* and *revenue*.",
[
('Billing engine', 'The system that decides what is owed, for which period and when to ask; the payment API only carries out the asking. It can be run by the payment provider, by a dedicated billing system or by your own code.', ['subscriptions-and-billing-engines'], []),
('Subscription', 'A standing agreement to charge a customer on a schedule.', ['subscriptions-and-billing-engines'], []),
('Billing cycle / anchor', 'The billing cycle is the repeating period a subscription bills for; its anchor is the point in time that fixes where each period starts.', ['subscriptions-and-billing-engines'], ['Billing cycle', 'Billing anchor']),
('Proration', 'Charging or crediting a fraction of a price because the customer changed plan part-way through a period.', ['subscriptions-and-billing-engines'], []),
('Billing scheduler', "The part of a billing engine that decides when: it finds subscriptions whose period has ended and triggers the next invoice. Half of a subscription's transitions come from the clock, with no request behind them.", ['subscriptions-and-billing-engines'], ['Scheduler']),
('Period record', "Under Keel, the row Larkfield's booking app writes before the first attempt of a renewal: membership, period, amount due and a state of `open`, `paid` or `void`. It is the record of the debt where the provider holds no invoice.", ['subscriptions-and-billing-engines', 'journey-failed-renewal'], []),
('Usage event', 'One record that a customer consumed something at a given time. Duplicates are removed by an identifier the producer of the event assigns.', ['usage-metering-and-rating'], []),
('Meter', 'The rule that turns many usage events into one quantity for a billing period, by sum, by count or by last value.', ['usage-metering-and-rating'], []),
('Rating', 'The step that applies a price plan to a metered quantity. Invoice-time rating needs a count that is correct eventually; a real-time balance check puts a read of a nearly current total into the product\'s request path.', ['usage-metering-and-rating'], ['Invoice-time rating', 'Real-time balance check']),
('Overage', "Usage above the amount a plan includes, billed per unit.", ['usage-metering-and-rating'], []),
('Credit balance / commitment', 'A credit balance is usage paid for or granted in advance and drawn down as usage is rated; a commitment is a promise of minimum spend over a period.', ['usage-metering-and-rating'], ['Credit balance', 'Commitment', 'Prepaid balance']),
('Invoice', 'A numbered, dated statement of what one customer owes one seller, for which goods or which period: the record of a debt. A payment is something else, one attempt to move money; a failed payment leaves an open invoice open.', ['invoicing-collections-and-dunning', 'subscriptions-and-billing-engines'], []),
('Finalized invoice', 'An invoice after the step that makes it a fixed document that may no longer change; corrections are made by a credit note.', ['invoicing-collections-and-dunning', 'usage-metering-and-rating'], ['Finalization']),
('Credit note', 'A document that reduces what is owed on an invoice and leaves the original as it was.', ['invoicing-collections-and-dunning'], []),
('Void / uncollectible', 'Void says the amount is not owed: the invoice was issued in error and is canceled, though its number stays on record. Uncollectible says the amount is owed and the seller has stopped expecting it.', ['invoicing-collections-and-dunning'], ['Void (invoice)', 'Uncollectible']),
('Dunning', 'The collection of an invoice whose payment failed or is overdue: retries, messages to the customer and a defined end.', ['invoicing-collections-and-dunning'], []),
('Involuntary churn', 'Customers lost for reasons outside their intent: an expired card, a changed bank account or a failed payment attempt.', ['invoicing-collections-and-dunning'], []),
('Retry schedule', 'The plan for when a failed payment is attempted again: fixed days, or a time chosen by a model inside a window the merchant sets.', ['invoicing-collections-and-dunning', 'authorization-optimization'], []),
('Cash application', 'Matching money that has arrived, typically by bank transfer, to the invoices it was meant to pay.', ['invoicing-collections-and-dunning'], []),
('Indirect tax', 'Value-added tax (VAT), sales tax or goods and services tax (GST): tax the seller collects from the buyer and pays to the state.', ['billing-and-payment-tax'], ['VAT', 'Sales tax', 'GST']),
('Tax calculation (one of four steps)', 'Working out the tax on a sale from location, product type and customer status. It is one of four steps, next to knowing where tax is due, registering there, and filing and paying; the liability for all four stays with the seller.', ['billing-and-payment-tax'], ['Tax calculation']),
('Tax registration / threshold', "A registration is the seller's enrollment with a tax authority, which allows and obliges it to collect that authority's tax. Whether a seller must register usually depends on a threshold, a volume of sales into the territory.", ['billing-and-payment-tax'], ['Tax registration', 'Registration threshold']),
('Deemed supplier', 'A platform that VAT law treats as if it had bought and resold what its sellers sell, so that the platform owes the tax. The EU rules cover goods (2021) and two service sectors (from 2028), not fitness studios.', ['billing-and-payment-tax'], []),
('Billings / cash / revenue', 'Billings are the amounts invoiced in a period; cash is what was collected; revenue is what was earned by delivering what was promised.', ['billing-revenue-recognition'], ['Billings', 'Revenue']),
('Performance obligation', 'A promise in a contract to transfer a distinct good or service to a customer; one contract may hold several (IFRS 15 and its US counterpart, ASC 606).', ['billing-revenue-recognition'], ['IFRS 15', 'ASC 606']),
('Deferred revenue', 'The part of an amount invoiced or collected that is not yet earned: a liability, because the seller owes either the service or the money back.', ['billing-revenue-recognition'], []),
('Revenue schedule', 'The dated plan by which deferred revenue becomes revenue.', ['billing-revenue-recognition'], []),
('Contra revenue', 'An account that reduces revenue without deleting the original entry, used when an amount already recognized is refunded or disputed.', ['billing-revenue-recognition'], []),
('Merchant of record', "The party that is legally the seller: it sells the product to the customer in its own name, commonly as a reseller, and so takes on tax, fraud losses, disputes and compliance for the sale.", ['merchant-of-record'], ['MoR']),
('Seller of record', "Often used for the merchant of record; Adyen's article reserves it for the legal owner of the goods at the time of sale and notes the two can be one entity.", ['merchant-of-record'], []),
('Liability transfer', "This book's name for the move of a legal responsibility (tax, fraud losses, disputes) from the business to the provider. A processor moves none; a payment facilitator moves more, and still not the sale.", ['merchant-of-record'], []),
]))

S.append(('g-platforms', 'Part VII — PLATFORMS: Paying Many Parties',
"Part VII's terms describe one decision seen four times: when a platform stands between payer and seller, who is the merchant, who holds the money and who carries the loss. Most of the vocabulary here is provider-specific and is translated in the [platforms crosswalk](#g-x-platforms).",
[
('Sponsored merchant', "A seller signed up by a payment facilitator under an acquirer; under the networks' rules it remains the merchant.", ['platform-payment-models'], []),
('Marketplace (network sense)', "In the networks' rules, a business that puts its own name ahead of its sellers and carries their disputes. Adyen also uses “marketplace” and “platform” for its two integration models (see the crosswalk).", ['platform-payment-models'], ['Marketplace']),
('Seller balance', "The provider's record of what it owes one seller on a platform; the seller's part of a split lands there until payout.", ['platform-payment-models', 'splits-balances-and-platform-payouts'], []),
('Account model', "The way a platform sets up its sellers' accounts and payments at the provider, which divides liability among three parties. Three models: the seller is the merchant and the provider bears its losses; the seller is the merchant and the platform stands behind it; the platform is the merchant.", ['platform-payment-models'], []),
('Hosted / embedded / API onboarding', "Three ways to collect verification data. Hosted: the seller leaves the platform's application for pages run by the provider. Embedded: a form drawn by the provider sits inside the platform's own page. API: the platform builds the forms and sends the data itself.", ['platform-onboarding-and-verification'], ['Hosted onboarding', 'Embedded onboarding', 'API onboarding']),
('Up-front / incremental onboarding', 'Collecting everything that will eventually be due before the seller starts, or only what is due now; the first avoids missed deadlines, the second lets sellers start quickly.', ['platform-onboarding-and-verification'], ['Up-front onboarding', 'Incremental onboarding']),
('Split', 'The instruction that divides one customer payment among the seller, the platform and the provider, by booking each part to a balance. It is a set of bookings inside the provider, not a movement between banks.', ['splits-balances-and-platform-payouts'], []),
('Transfer', 'A movement of money between two balances inside the provider; a payout moves it from a balance to a bank account outside. (Adyen also calls a payout to a bank account a transfer; see the crosswalk.)', ['splits-balances-and-platform-payouts', 'payouts-and-money-movement'], []),
('Top-up', 'Bank money added to a balance at the provider that did not come from a customer payment.', ['splits-balances-and-platform-payouts'], []),
('Exposure (after payout)', 'The amount that can still come back through a refund or a chargeback after a seller has been paid: at Larkfield, the online card volume paid out in the last 120 days, less the refunds and disputes already booked.', ['splits-balances-and-platform-payouts', 'journey-platform-payment'], []),
('Seller-first / platform-first booking / collect, then distribute', "Three designs for a split: the payment lands in the seller's balance and only the platform's fee moves; it lands in the platform's balance and the seller's share moves out; or it stays on the platform until the platform decides who gets what.", ['splits-balances-and-platform-payouts'], ['Seller-first booking', 'Platform-first booking', 'Collect, then distribute']),
('Banking-as-a-service', "A licensed institution's accounts, cards or loans offered through another company's software. The license covers the regulated act, not the platform's operating duties.", ['embedded-finance'], ['Embedded finance']),
('Financial account', "An account at the provider that keeps a seller's balance instead of paying it out to a bank elsewhere, and can send and receive transfers.", ['embedded-finance'], ['Stored balance']),
('Card issuing', "Giving a seller a card that spends its balance. It reverses the roles of an authorization: the provider is the issuer, and the platform's server has two seconds to approve or decline each purchase.", ['embedded-finance'], ['Issuing']),
('Embedded lending', 'An advance of money against future sales, repaid as a fixed percentage of processed volume.', ['embedded-finance'], ['Financing']),
]))

S.append(('g-scale', 'Part VIII — SCALE: Reliability, Data and Operations',
"Part VIII's terms describe what is allowed to give way under failure, load and change so that the record of money does not. In a money path the order of priorities is the reverse of a content site's.",
[
('Availability / availability target', 'Availability is the share of time, or of requests, in which a service answers correctly (“five nines” is 99.999%). An availability target is an internal goal; a service-level agreement (SLA) is a contractual commitment with consequences if missed. The period matters as much as the percentage.', ['payment-reliability-and-availability'], ['Availability', 'Availability target', 'Uptime', 'SLA']),
('Failure isolation', 'Arranging a system so that one broken part cannot take the rest down.', ['payment-reliability-and-availability'], []),
('Graceful degradation', 'Continuing to serve the important requests, in a reduced way, while something is broken; it requires having decided beforehand what may lag or be dropped.', ['payment-reliability-and-availability'], []),
('Fail open / queue / fail closed', 'Three answers when a step of the payment path is unavailable: skip the step and let the payment proceed; accept the payment and do the step later from a durable record; or refuse or hold the payment.', ['payment-reliability-and-availability'], ['Fail open', 'Fail closed']),
('Incident report (postmortem)', 'A written account of what failed, why and what will change; also called a root-cause analysis.', ['payment-reliability-and-availability', 'payment-safe-change'], ['Postmortem', 'Root-cause analysis', 'Incident report']),
('Consistency boundary', 'The set of records that change together in one local transaction, or not at all; no larger than one database. Everything outside it is reached by a call or message that can fail on its own.', ['payment-data-stores-and-consistency'], []),
('Shard / shard key', 'A shard is one of many databases that each hold a slice of the same kind of data; the shard key is the rule that decides where a record goes. A partition, by contrast, is a slice of one table inside one database, so a transaction still covers all of it.', ['payment-data-stores-and-consistency'], ['Shard', 'Shard key', 'Partition']),
('Online migration', 'Changing where or how live data is stored while the system keeps serving requests.', ['payment-data-stores-and-consistency', 'payment-safe-change'], []),
('Outbox', 'A table in the same database as the business data: the state change and a row describing the message are written in one local transaction, and a separate relay publishes the rows until each is acknowledged.', ['payment-data-stores-and-consistency'], ['Transactional outbox']),
('Data residency / data localization', 'Data residency is a fact: where data is stored. Data localization is a law that requires data to be stored, sometimes only, in one country.', ['payment-multi-region-and-data-residency'], ['Data residency', 'Data localization']),
('Active-passive / active-active', 'In active-passive operation one region serves and another waits to take over; in active-active several serve at once, which needs a rule for which region writes which record.', ['payment-multi-region-and-data-residency'], ['Active-active', 'Active-passive']),
('Peak profile', 'A description of a peak by three things: its shape over time, who creates it, and whether a customer is waiting for the answer.', ['payment-peak-load'], []),
('Load test', "The deliberate sending of artificial traffic to a system to find its weakest part before real customers do.", ['payment-peak-load'], []),
('Fairness', "In a shared API, the property that no customer's traffic can take capacity another customer needs.", ['payment-peak-load'], []),
('Backpressure', 'A slow part of a system making the faster part upstream slow down.', ['payment-peak-load'], []),
('Progressive rollout', 'Sending a change to a small share of live traffic and widening the share only while metrics stay healthy; also called a canary release.', ['payment-safe-change'], ['Canary release']),
('Feature flag', 'A switch that turns a behavior on or off in production without a new deployment, which separates deploying code from activating it.', ['payment-safe-change'], ['Toggle']),
('Zero-downtime migration', 'Changing a schema or moving data while requests continue; harder than a code rollout because rows written by the new code remain after it is withdrawn, and the old code must still read them.', ['payment-safe-change'], []),
('Dark launch', 'Running new code on real traffic without letting its result reach the customer; also called shadowing.', ['payment-safe-change'], ['Shadowing']),
]))

S.append(('g-journeys', 'Part IX — JOURNEYS: One Payment, End to End',
"Part IX adds almost no vocabulary: it shows the terms of Parts I–VIII at work on four payments. The few entries here name the form of a journey; the people, amounts and dates are in the [Larkfield table](#g-larkfield).",
[
('Step table', 'The table at the center of each journey: one row per step, naming the party or system, the message or record, the promise made, and what can fail there with its chapter.', ['part-9', 'journey-card-payment'], []),
('Hand-off', "The point where one mechanism's answer (an approval, a decline, a payout, a payment marked complete) is taken by the next system as final. Every failure the journeys show appears at one.", ['part-9'], []),
('Which later record confirms this one?', "The question each journey asks of every record. The answer depends on references that survive from one system to the next: your own payment ID, the idempotency key, the provider's payment identifier, the funding unit and the payout.", ['journey-card-payment'], []),
]))

S.append(('g-bets', 'Part X — BETS: Where Stripe and Adyen Diverge',
"Part X's terms are the measures and labels used to read two company records side by side, and the changes under way in 2026. Figures and statuses are as of November 2026.",
[
('Processed volume / full-stack volume', "Processed volume is the value of the payments Adyen handled. Its annual report for 2025 says 84% of it was “full-stack” and does not define the term there; volume settled by an external acquirer is part of the rest.", ['case-adyen'], ['Processed volume', 'Full-stack volume']),
('EBITDA margin', 'EBITDA divided by net revenue, as Adyen reports it.', ['case-adyen'], []),
('Difference of kind / difference of default, sequence or degree', "The comparison chapter's test. If both companies document a structural fact and the facts differ in type, it is a difference of kind (a bank is not an e-money institution). If they are of the same type and differ in amount, order or default, it is a difference of default, sequence or degree. If at least one has published nothing, the question is not decidable from the public record.", ['stripe-and-adyen-bets-compared'], ['Difference of kind', 'Not decidable from the public record']),
('Announced / preview / limited availability / generally available', "The release labels the last chapters use, in the vendors' own words. Announced: a press release and nothing a customer can use. Preview: usable by invitation (private) or by anyone who accepts that it may change (public). Limited availability: released to a named group. Generally available: open to any eligible customer.", ['payments-what-is-moving', 'embedded-finance'], ['General availability', 'Public preview', 'Private preview', 'Limited availability', 'Pilot']),
('Agentic commerce', "Software agents that find, choose and pay for goods on a person's behalf. The issuer is asked to approve a payment the cardholder did not key in, on a credential delegated to an agent.", ['payments-what-is-moving'], ['Agent payments']),
('Agent payment protocols (AP2, ACP, UCP, MPP)', "Open protocols for agent payments that coexisted in November 2026: Google's Agent Payments Protocol (2025), the Agentic Commerce Protocol of Stripe and OpenAI (2025, in beta), the Universal Commerce Protocol (2026) and the Machine Payments Protocol co-authored by Stripe and Tempo (2026).", ['payments-what-is-moving'], ['AP2', 'ACP', 'UCP', 'MPP']),
('Stablecoin', 'A token on a blockchain which its issuer promises to redeem one for one for a currency such as the US dollar, and backs with reserves.', ['payments-what-is-moving'], []),
('Instant payment', "A transfer the payer pushes from a bank account, which reaches the payee's account within seconds, at any hour, on any day. It pays no interchange.", ['payments-what-is-moving', 'local-payment-methods'], ['SEPA Instant']),
]))

AX = ('g-larkfield', 'Larkfield Names (Fictional)',
"**Larkfield is fictional**: a Rotterdam software platform for independent fitness and wellness studios, invented for teaching and introduced in [[meet-larkfield]]. It uses Stripe and Adyen by name because the book compares the two, but what it experiences with a provider is illustration, never evidence about the provider. Its own systems are named by role. Every name, figure and date below agrees with the book's scenario ledger; the scenes are set in 2027, after the November 2026 date of the real-world entries.",
[
('Larkfield B.V.', 'The fictional platform the book follows: founded in Rotterdam in 2017; in 2026, 6,200 studios, 2.9 million active members, €1.12 billion in 31.4 million payments processed for studios and €46.0 million of its own revenue; 340 employees, 11 in the payments team. It is not a payment institution and not the merchant of record for class sales.', ['meet-larkfield'], ['Larkfield']),
('Two providers, split by studio', "Stripe since 2017 (44% of 2026 volume: the United Kingdom, the United States, Belgium and studios not yet migrated) and Adyen since 2024 (56%: every front-desk terminal, and online payments of Dutch and German studios onboarded or migrated since 2024). A studio's online payments are on one provider.", ['meet-larkfield'], ['The split studios', '1,140 studios']),
('The split studios', '1,140 studios in the Netherlands and Germany, onboarded before 2024, that take online payments on Stripe and front-desk payments on Adyen terminals; the source of several incidents.', ['meet-larkfield', 'in-person-payments'], []),
('Femke de Graaf', "Head of Payments Engineering since January 2027 (she/her): an experienced engineer new to payments, the reader's stand-in, who leads Keel.", ['meet-larkfield'], []),
('Daniel Osei', 'CTO and co-founder (he/him); wrote the original Stripe integration in 2017.', ['meet-larkfield'], []),
('Sofie Vermeer', 'CEO and co-founder (she/her).', ['meet-larkfield'], []),
('Priya Raman', 'Finance Controller (she/her); owns the monthly close and the audit finding.', ['meet-larkfield', 'payment-reconciliation-and-reporting'], []),
('Jonas Weber', 'Risk and Compliance Lead (he/him); owns verification, disputes and the fraud rules.', ['meet-larkfield', 'licences-and-safeguarding'], []),
('Aylin Demir', 'Head of Studio Support (she/her); hears about every payout problem first.', ['meet-larkfield', 'payouts-and-money-movement'], []),
('Tom Hendriks', 'Senior engineer in the payments team (he/him); built the payment service in 2024.', ['meet-larkfield'], []),
('Ines Bakker / Studio Noord', 'Ines Bakker (she/her) owns Studio Noord, a yoga studio in Utrecht with three instructors and 410 members, on Adyen since 2024; the seller in most worked examples.', ['meet-larkfield', 'journey-card-payment'], ['Ines Bakker', 'Studio Noord']),
('Ravi Shah / Ironworks Climbing', 'Ravi Shah (he/him) owns Ironworks Climbing, three locations in Manchester, on Stripe Connect; the onboarding example and the buyer of the annual plan.', ['meet-larkfield', 'platform-onboarding-and-verification'], ['Ravi Shah', 'Ironworks Climbing']),
('Mila Janssen', 'Member at Studio Noord (she/her); the payer in the recurring payment and in the membership renewal.', ['meet-larkfield', 'journey-card-payment'], []),
('Bram de Wit', 'Member at Studio Noord (he/him); the cardholder in the €120 dispute.', ['meet-larkfield', 'journey-dispute'], []),
('Daan Peters', 'Member at Studio Noord (he/him); pays his membership by direct debit.', ['meet-larkfield', 'local-payment-methods'], []),
('Lotte Smit', 'Member at Studio Noord (she/her); her bank replaces her stored card in February 2027 and her renewal of 1 March is approved through a network token.', ['meet-larkfield', 'network-tokens'], []),
('The booking app', "The member-facing web and mobile app and the studios' back office; it creates the business events (purchase, renewal, refund request).", ['meet-larkfield'], []),
('The payment service', 'One internal API for “take a payment”, “refund” and “pay out”, with an adapter per provider; built in 2024, it routes by studio and holds the idempotency keys.', ['meet-larkfield', 'payment-api-design'], []),
('The payment record store', "Larkfield's own record of every payment attempt in five states (`pending`, `authorized`, `paid`, `refunded`, `disputed`), with both providers' references; fed by webhooks through an inbox table.", ['meet-larkfield', 'payment-state-machines'], ['Five-state vocabulary']),
('The ledger (Larkfield)', 'A small double-entry ledger of what Larkfield and the studios are owed, per provider and currency, introduced in 2025; under K3 its entries are written only from provider report lines.', ['meet-larkfield', 'payment-ledgers'], []),
('The billing integration', "The Stripe Billing objects for studio subscriptions and a meter for SMS usage; owned by the growth team until May 2027.", ['meet-larkfield', 'subscriptions-and-billing-engines'], []),
('The webhook receivers', 'One endpoint per provider: verify, persist, acknowledge, process asynchronously. The Stripe receiver predates the payment service.', ['meet-larkfield', 'payment-webhooks-and-events'], []),
('The reconciliation job', 'Compares provider reports with the payment record store and the ledger; it covered only Adyen until Keel, and under K3 runs once per provider on that provider\'s report-ready signal.', ['meet-larkfield', 'payment-reconciliation-and-reporting'], []),
('The data warehouse / the front-desk app', 'The data warehouse holds reporting for finance and studios, fed by provider exports. The front-desk app is the tablet app that drives the Adyen terminals over a cloud connection, with no offline mode.', ['meet-larkfield', 'in-person-payments'], ['The data warehouse', 'The front-desk app']),
("Mila's class pass", 'The recurring payment: on Tuesday 9 March 2027 at 19:42 Mila Janssen buys a ten-class pass for €120.00 from Studio Noord with the Dutch Visa debit card in her phone\'s wallet. Larkfield\'s fee is €2.53 and the studio receives €117.47; the payout is sent on Thursday 11 March and the payment can be disputed until about 7 July.', ['meet-larkfield', 'journey-card-payment'], ['The recurring payment']),
("Mila's membership renewal", "A €49.00 monthly membership set up on 12 January 2027 with a 3-D Secure challenge and renewed on the 1st as a merchant-initiated payment; the renewal of 1 April 2027 is declined for insufficient funds and succeeds on the retry of 4 April.", ['meet-larkfield', 'journey-failed-renewal'], []),
('The refund after payout', 'On 18 March 2027 Mila asks for €84.00 back, the seven unused classes of her pass, a week after Studio Noord was paid.', ['meet-larkfield', 'journey-platform-payment'], []),
('The €120 dispute', "Bram de Wit disputes as “not recognized” a €120.00 pass bought at Studio Noord on 2 February 2027 with a Dutch Mastercard credit card; the chargeback arrives on 24 February with a €15.00 dispute fee *(illustrative)*. Under Larkfield's terms the studio carries a lost dispute; if its balance cannot cover it, the loss falls on Larkfield.", ['meet-larkfield', 'journey-dispute'], []),
('The annual plan', 'Ironworks Climbing pays €1,890 up front on 1 February 2027 for an annual €189 plan at one location: cash in one day, revenue earned over 365.', ['meet-larkfield', 'billing-revenue-recognition'], []),
('The first of the month', 'About 940,000 membership renewals a month, about €46 million; 38% of them (about 357,000 renewals, €17.5 million) are attempted in the first six hours of the 1st.', ['meet-larkfield', 'payment-peak-load'], []),
('The Double Charge (incident)', '1 November 2026: a provider call timed out during the first-of-month renewals and the renewal job retried with a new idempotency key; 1,840 members were charged twice, €71,300 was refunded and 212 disputes followed anyway.', ['meet-larkfield', 'idempotency-and-retries'], []),
('The Silent Webhook', "Monday 14 September 2026: the Stripe webhook receiver's TLS certificate expired shortly after midnight and events failed for 9 hours; 3,200 memberships were shown as unpaid and members were turned away at check-in.", ['meet-larkfield', 'payment-webhooks-and-events'], []),
('The Payout That Bounced', 'June 2026: a form let studio owners change bank details without verification of the account holder; 412 payouts worth €386,000 were returned by receiving banks over three weeks and sat unreconciled.', ['meet-larkfield', 'payouts-and-money-movement'], []),
('The Version Cliff (incident)', "March 2026: the billing integration ran on the Stripe account's default API version, by then more than three years old; a library upgrade carried a newer version across a breaking release that removed a field the finance export read, and subscription revenue reports were wrong for 6 days.", ['meet-larkfield', 'payment-api-versioning'], []),
('The Card-Testing Weekend', "8–9 August 2026: bots used one studio's public booking widget to test 61,000 stolen card numbers with €1 drop-in payments; €4,100 in fees and refunds, and the studio's online payments were off for 31 hours.", ['meet-larkfield', 'payment-fraud-and-risk'], []),
('The Renewal Wave', "38% of monthly membership volume is attempted in a 6-hour window on the 1st. On 1 October 2026 the renewal job hit the provider's rate limit and 7,900 renewals were delayed to the next day; dunning emails went to members who had done nothing wrong.", ['meet-larkfield', 'payment-peak-load', 'payment-developer-platform'], []),
('The Frozen Studios', "May 2026: a verification requirement changed and 230 studios missed the deadline because Larkfield's reminder went to an unmonitored address; their payouts were paused for up to 12 days.", ['meet-larkfield', 'payment-compliance-and-regulation'], []),
('The Unexplained €0.4 Million', "Year-end 2025: the ledger's “owed to studios” balance was €412,000 higher than the two providers' balances; traced in January 2026 to refunds after payout (€317,200), chargeback fees (€73,500) and a currency-conversion rounding rule (€21,300).", ['meet-larkfield', 'payment-ledgers'], []),
('Keel', "Larkfield's 2027 program, led by Femke de Graaf, that puts the payments estate on an even keel. Its eight decisions K1–K8 are fixed: chapters explain them and never change them.", ['meet-larkfield'], ['Keel program']),
('K1 — One writer, one key', 'Every money-moving call goes through the payment service, and its idempotency key is derived from the business event, never generated per network call; for a renewal: membership, billing period and the number of the scheduled attempt.', ['meet-larkfield', 'idempotency-and-retries'], ['K1']),
('K2 — The provider\'s record is the truth; the webhook is the doorbell', "Receivers verify, persist and acknowledge; a state change is confirmed against the provider's own record (the payment object where the API lets Larkfield read it, the settlement report where it does not); a job sweeps everything still pending.", ['meet-larkfield', 'payment-webhooks-and-events'], ['K2']),
('K3 — A ledger entry for every movement', 'Fees, splits, refunds, disputes, payouts and returns are entries; clearing accounts must return to zero; the reconciliation job covers both providers, one run per provider.', ['meet-larkfield', 'payment-ledgers', 'payment-reconciliation-and-reporting'], ['K3']),
('K4 — Card numbers never touch Larkfield', 'Hosted fields and provider tokens only; network tokens for stored cards; a script inventory for the booking widget.', ['meet-larkfield', 'tokenization-vaulting-and-pci'], ['K4']),
('K5 — Renewals are spread and rate-limited by Larkfield, not by the provider', 'The renewal job paces itself over 18 hours and retries on a schedule tied to decline codes.', ['meet-larkfield', 'payment-peak-load'], ['K5']),
('K6 — Verification is state, not a form', "Each studio's requirements, deadlines and capability status are mirrored and shown in the back office, with an owner for every deadline.", ['meet-larkfield', 'platform-onboarding-and-verification'], ['K6']),
('K7 — Versions are upgraded on a calendar', 'One planned API upgrade per provider per half-year, tested against recorded traffic.', ['meet-larkfield', 'payment-api-versioning'], ['K7']),
('K8 — Two providers, one rehearsed switch', "The payment service can move a studio's online card payments to the other provider; the switch is rehearsed quarterly for the 50 largest studios; no orchestration product is added.", ['meet-larkfield', 'payment-routing-and-orchestration'], ['K8']),
('The platform fee', "What Larkfield charges a studio on each member payment: 1.9% + €0.25 per online card payment, 0.8% + €0.25 per direct debit, €0.35 per iDEAL payment and 1.4% + €0.10 per in-person payment. The provider's processing cost comes out of that fee.", ['meet-larkfield', 'payment-economics'], ['Platform fee (Larkfield)']),
('The acquirer inventory', 'A list Femke de Graaf starts in February 2027: one row per provider and market with the acquirer of record, its license and whether a bank stands between studio and network, filled from the providers\' public pages.', ['acquiring-and-network-connectivity'], ['Acquirer inventory']),
('The version register', 'The start of K7: one row for each place an API version is set, with its current value, an owner and the date it was last moved.', ['payment-api-versioning'], ['Version register']),
('The instant-payout card', 'A May 2027 proposal by the product team to give studios a card that spends their balance; Larkfield decided not to launch it yet.', ['embedded-finance'], []),
('The refund buffer', "An April 2027 proposal to collect member payments into a Larkfield bank account and pay studios 14 days later, about €43 million held at any moment. Jonas Weber stopped it: holding money that is not Larkfield's is a regulated activity.", ['licences-and-safeguarding'], []),
])
